@Override
	public void guard(SkillContainer container, CapabilityItem itemCapability, ServerPlayerPatch playerPatch, TakeDamageEvent.Income event, float knockback, float impact, boolean advanced) {
		if (this.isHoldingWeaponAvailable(playerPatch, itemCapability, BlockType.ADVANCED_GUARD)) {
			DamageSource damageSource = event.getDamageSource();
			Entity offender = getOffender(damageSource);

			if (offender != null && this.isBlockableSource(damageSource, true)) {
				ServerPlayer serverplayer = playerPatch.getOriginal();
				boolean successParrying = serverplayer.tickCount - container.getDataManager().getDataValue(EpicFightSkillDataKeys.LAST_ACTIVE) < this.parryWindow;
				float penalty = container.getDataManager().getDataValue(EpicFightSkillDataKeys.PENALTY);
				playerPatch.playSound(EpicFightSounds.CLASH.get(), -0.05F, 0.1F);
				EpicFightParticles.HIT_BLUNT.get().spawnParticleWithArgument(serverplayer.serverLevel(), HitParticleType.FRONT_OF_EYES, HitParticleType.ZERO, serverplayer, offender);

				if (successParrying) {
					event.setParried(true);
					penalty = 0.1F;
					knockback *= 0.4F;

					// Solution by Cyber2049(github): Fix continuous parry
					container.getDataManager().setData(EpicFightSkillDataKeys.LAST_ACTIVE, 0);
				} else {
					penalty += this.getPenalizer(itemCapability);
					container.getDataManager().setDataSync(EpicFightSkillDataKeys.PENALTY, penalty);
				}

				if (offender instanceof LivingEntity livingentity) {
					float modifiedKnockback = EnchantmentHelper.modifyKnockback(serverplayer.serverLevel(), livingentity.getItemInHand(livingentity.getUsedItemHand()), livingentity, damageSource, knockback);
					knockback = (modifiedKnockback - knockback) * 0.1F;
				}

                playerPatch.knockBackEntity(offender.position(), knockback);
				float consumeAmount = penalty * impact;
				boolean canAfford = playerPatch.consumeForSkill(this, Skill.Resource.STAMINA, consumeAmount);

				BlockType blockType = successParrying ? BlockType.ADVANCED_GUARD : (canAfford ? BlockType.GUARD : BlockType.GUARD_BREAK);
				AnimationAccessor<? extends StaticAnimation> animation = this.getGuardMotion(container, playerPatch, itemCapability, blockType);

				if (animation != null) {
					playerPatch.playAnimationSynchronized(animation, 0);
				}

				if (blockType == BlockType.GUARD_BREAK) {
					playerPatch.playSound(EpicFightSounds.NEUTRALIZE_MOBS.get(), 3.0F, 0.0F, 0.1F);
				}

				this.dealEvent(playerPatch, event, advanced);

				return;
			}
		}

		super.guard(container, itemCapability, playerPatch, event, knockback, impact, false);
	}

@Override
    public void onInitiate(SkillContainer skillContainer, EntityEventListener eventListener) {
        eventListener.registerEvent(
            EpicFightClientEventHooks.Entity.MODIFY_PLAYER_LIVING_MOTION_COMPOSITE,
            event -> {
                if (
                    skillContainer.isActivated() &&
                    // Use the active combat cap so guarding works with an offhand-only weapon
                    // in mirror mode -- otherwise the bare mainhand would fail the available-weapon
                    // check and the BLOCK motion would never trigger on the visual side.
                    this.isHoldingWeaponAvailable(skillContainer.getExecutor(), skillContainer.getExecutor().getPrimaryItemCapability(), GuardSkill.BlockType.GUARD)
                ) {
                    event.setMotion(LivingMotions.BLOCK);
                }
            },
            this
        );

        eventListener.registerEvent(
            EpicFightClientEventHooks.Control.MAPPED_MOVEMENT_INPUT_UPDATE,
            event -> {
                if (skillContainer.isActivated() && skillContainer.getExecutor().getHoldingSkill() == this) {
                    skillContainer.getExecutor().getOriginal().setSprinting(false);
                    skillContainer.getClientExecutor().getOriginal().sprintTriggerTime = -1;

                    ControlEngine.setSprintingKeyStateNotDown();
                    final PlayerInputState current = event.getInputState();
                    final PlayerInputState updated = current
                        .withForwardImpulse(current.forwardImpulse() * 0.5f)
                        .withLeftImpulse(current.leftImpulse() * 0.5f);
                    InputManager.setInputState(updated);
                }
            },
            this
        );

        eventListener.registerEvent(
            EpicFightEventHooks.Entity.TAKE_DAMAGE_INCOME,
            event -> {
                CapabilityItem itemCapability = skillContainer.getExecutor().getPrimaryItemCapability();

                if (skillContainer.isActivated() && skillContainer.getExecutor().getHoldingSkill() == this) {
                    DamageSource damageSource = event.getDamageSource();
                    boolean isFront = false;
                    Vec3 sourceLocation = damageSource.getSourcePosition();

                    if (sourceLocation != null) {
                        Vec3 viewVector = skillContainer.getExecutor().getOriginal().getViewVector(1.0F);
                        viewVector = viewVector.subtract(0, viewVector.y, 0).normalize();
                        Vec3 toSourceLocation = sourceLocation.subtract(skillContainer.getExecutor().getOriginal().position()).normalize();

                        if (toSourceLocation.dot(viewVector) > 0.0D) {
                            isFront = true;
                        }
                    }

                    if (isFront) {
                        float impact = 0.5F;
                        float knockback = 0.25F;

                        if (event.getDamageSource() instanceof EpicFightDamageSource epicfightDamageSource) {
                            if (epicfightDamageSource.is(EpicFightDamageTypeTags.GUARD_PUNCTURE)) {
                                return;
                            }

                            impact = epicfightDamageSource.calculateImpact();
                            knockback += Math.min(impact * 0.1F, 1.0F);
                        }

                        this.guard(skillContainer, itemCapability, skillContainer.getServerExecutor(), event, knockback, impact, false);
                    }
                }
            },
            this,
            1
        );

        eventListener.registerEvent(
            EpicFightEventHooks.Entity.DELIVER_DAMAGE_POST,
            event -> {
                // clears penalty multiplier on hit
                skillContainer.getDataManager().setDataSync(EpicFightSkillDataKeys.PENALTY, 0.0F);
            },
            this
        );
    }

public void guard(SkillContainer container, CapabilityItem itemCapability, ServerPlayerPatch playerPatch, TakeDamageEvent.Income event, float knockback, float impact, boolean advanced) {
		DamageSource damageSource = event.getDamageSource();
		Entity offender = getOffender(damageSource);

		if (offender != null && this.isBlockableSource(damageSource, advanced)) {
			playerPatch.playSound(EpicFightSounds.CLASH.get(), -0.05F, 0.1F);
			ServerPlayer serverPlayer = playerPatch.getOriginal();
			EpicFightParticles.HIT_BLUNT.get().spawnParticleWithArgument(serverPlayer.serverLevel(), HitParticleType.FRONT_OF_EYES, HitParticleType.ZERO, serverPlayer, offender);

			if (offender instanceof LivingEntity livingEntity) {
				float modifiedKnockback = EnchantmentHelper.modifyKnockback((ServerLevel)livingEntity.level(), livingEntity.getItemInHand(livingEntity.getUsedItemHand()), livingEntity, damageSource, knockback);
				knockback = (modifiedKnockback - knockback) * 0.1F;
			}

			float penalty = container.getDataManager().getDataValue(EpicFightSkillDataKeys.PENALTY) + this.getPenalizer(itemCapability);
			float consumeAmount = penalty * impact;
			boolean canAfford = playerPatch.consumeForSkill(this, Skill.Resource.STAMINA, consumeAmount);

			playerPatch.knockBackEntity(offender.position(), knockback);
			container.getDataManager().setDataSync(EpicFightSkillDataKeys.PENALTY, penalty);
			container.getDataManager().setDataSync(EpicFightSkillDataKeys.PENALTY_RESTORE_COUNTER, container.getServerExecutor().getOriginal().tickCount);

			BlockType blockType = canAfford ? BlockType.GUARD : BlockType.GUARD_BREAK;
			AnimationAccessor<? extends StaticAnimation> animation = this.getGuardMotion(container, playerPatch, itemCapability, blockType);

			if (animation != null) {
				playerPatch.playAnimationSynchronized(animation, 0.0F);
			}

			if (blockType == BlockType.GUARD_BREAK) {
				playerPatch.playSound(EpicFightSounds.NEUTRALIZE_MOBS.get(), 3.0F, 0.0F, 0.1F);
			}

			this.dealEvent(playerPatch, event, advanced);
		}
	}

public void dealEvent(PlayerPatch<?> playerPatch, TakeDamageEvent.Income event, boolean advanced) {
		event.cancel();
		event.setResult(AttackResult.ResultType.BLOCKED);
		playerPatch.countHurtTime(event.getDamage());

		EpicFightCapabilities.getUnparameterizedEntityPatch(event.getDamageSource().getEntity(), LivingEntityPatch.class)
			.ifPresent(attackerpatch -> attackerpatch.setLastAttackEntity(playerPatch.getOriginal()));

		EpicFightCapabilities.<LivingEntity, LivingEntityPatch<LivingEntity>>getParameterizedEntityPatch(event.getDamageSource().getDirectEntity(), LivingEntity.class, LivingEntityPatch.class)
			.ifPresent(entitypatch -> entitypatch.onAttackBlocked(event.getDamageSource(), playerPatch));
	}

@Override
	public void cancelOnServer(SkillContainer skillContainer, CompoundTag arguments) {
		skillContainer.deactivate();
		skillContainer.getExecutor().resetHolding();

        EpicFightEventHooks.Player.CANCEL_SKILL.postWithListener(new SkillCancelEvent(skillContainer.getServerExecutor(), skillContainer), skillContainer.getExecutor().getEventListener());
		EpicFightNetworkManager.sendToAllPlayerTrackingThisEntity(SPSetSkillContainerValue.activate(skillContainer.getSlot(), false, skillContainer.getExecutor().getOriginal().getId()), skillContainer.getExecutor().getOriginal());
	}

@Override
	public void startHolding(SkillContainer container) {
		container.activate();
		container.runOnServer(serverplayerpatch -> EpicFightNetworkManager.sendToAllPlayerTrackingThisEntity(SPSetSkillContainerValue.activate(container.getSlot(), true, serverplayerpatch.getOriginal().getId()), serverplayerpatch.getOriginal()));
	}

@Override
	public void holdTick(SkillContainer container) {
		container.runOnServer(serverplayerpatch -> {
			if (container.isActivated()) {
				container.getDataManager().setDataSync(EpicFightSkillDataKeys.PENALTY_RESTORE_COUNTER, container.getServerExecutor().getOriginal().tickCount);
			}
		});
	}

@Override
	public void resetHolding(SkillContainer container) {
		container.deactivate();
	}

public void onStopHolding(SkillContainer container, SPSkillFeedback feedback) {
		container.deactivate();
	}

protected boolean isBlockableSource(DamageSource damageSource, boolean advanced) {
		return !damageSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)
				&& !damageSource.is(EpicFightDamageTypeTags.UNBLOCKALBE)
				&& !damageSource.is(DamageTypeTags.BYPASSES_ARMOR)
				&& !damageSource.is(DamageTypeTags.IS_PROJECTILE)
				&& !damageSource.is(DamageTypeTags.IS_EXPLOSION)
				&& !damageSource.is(DamageTypes.MAGIC)
				&& !damageSource.is(DamageTypeTags.IS_FIRE);
	}

public static Entity getOffender(DamageSource damageSource) {
		return damageSource.getDirectEntity() == null ? damageSource.getEntity() : damageSource.getDirectEntity();
	}

public boolean isHoldingWeaponAvailable(PlayerPatch<?> playerpatch, CapabilityItem itemCapability, BlockType blockType) {
		AnimationAccessor<? extends StaticAnimation> anim = itemCapability.getGuardMotion(this, blockType, playerpatch);

		if (anim != null) {
			return true;
		}

		Map<WeaponCategory, BiFunction<CapabilityItem, PlayerPatch<?>, ?>> guardMotions = this.getGuardMotionMap(blockType);

		if (!guardMotions.containsKey(itemCapability.getWeaponCategory())) {
			return false;
		}

        Object motion = guardMotions.get(itemCapability.getWeaponCategory()).apply(itemCapability, playerpatch);

		return motion != null;
	}

@Override
	public void updateContainer(SkillContainer container) {
		super.updateContainer(container);

		container.runOnServer(serverplayerpatch -> {
			if (!container.getExecutor().isHoldingSkill(this)) {
				float penalty = container.getDataManager().getDataValue(EpicFightSkillDataKeys.PENALTY);

				if (penalty > 0.0F) {
					int hitTick = container.getDataManager().getDataValue(EpicFightSkillDataKeys.PENALTY_RESTORE_COUNTER);

					if (container.getExecutor().getOriginal().tickCount - hitTick > 40) {
						container.getDataManager().setDataSync(EpicFightSkillDataKeys.PENALTY, 0.0F);
					}
				}
			} else {
				container.getExecutor().resetActionTick();
			}
		});
	}

@Override
    public void onInitiate(SkillContainer skillContainer, EntityEventListener eventListener) {
        super.onInitiate(skillContainer, eventListener);

        skillContainer.runOnServer(playerpatch -> {
            CapabilityItem itemCapability = skillContainer.getExecutor().getPrimaryItemCapability();

            if (this.isHoldingWeaponAvailable(skillContainer.getExecutor(), itemCapability, BlockType.GUARD) && this.isExecutableState(skillContainer.getExecutor())) {
                // Trigger use-item on whichever hand actually holds the weapon so the offhand-only
                // case begins parrying instead of attempting to use the empty mainhand.
                skillContainer.getExecutor().getOriginal().startUsingItem(skillContainer.getExecutor().getPrimaryHand());
            }

            int lastActive = skillContainer.getDataManager().getDataValue(EpicFightSkillDataKeys.LAST_ACTIVE);

            if (skillContainer.getExecutor().getOriginal().tickCount - lastActive > this.parryWindow * 2) {
                skillContainer.getDataManager().setData(EpicFightSkillDataKeys.LAST_ACTIVE, skillContainer.getExecutor().getOriginal().tickCount);
            }
        });
    }

@Override
	public void startHolding(SkillContainer skillContainer) {
		super.startHolding(skillContainer);

		skillContainer.runOnServer(serverExecutor -> {
			 int lastActive = skillContainer.getDataManager().getDataValue(EpicFightSkillDataKeys.LAST_ACTIVE);
			 if (serverExecutor.getOriginal().tickCount - lastActive > this.parryWindow * 2) {
				 skillContainer.getDataManager().setDataSync(EpicFightSkillDataKeys.LAST_ACTIVE, serverExecutor.getOriginal().tickCount);
			 }
		});
	}

@Override
	public void loadDatapackParameters(CompoundTag parameters) {
		super.loadDatapackParameters(parameters);

		this.parryWindow = parameters.getInt("parry_window");

		if (this.parryWindow <= 0) {
			this.parryWindow = 8;
		}
	}

@Override
	protected boolean isBlockableSource(DamageSource damageSource, boolean advanced) {
		return (damageSource.is(DamageTypeTags.IS_PROJECTILE) && advanced) || super.isBlockableSource(damageSource, false);
	}

@Nullable
	protected AnimationAccessor<? extends StaticAnimation> getGuardMotion(SkillContainer container, PlayerPatch<?> playerpatch, CapabilityItem itemCapability, BlockType blockType) {
		if (blockType != BlockType.ADVANCED_GUARD)
        {
            return super.getGuardMotion(container, playerpatch, itemCapability, blockType);
        }
        SkillDataManager dataManager = container.getDataManager();
        AnimationAccessor<? extends StaticAnimation> result = itemCapability.getGuardMotion(this, blockType, playerpatch);
		if (result == null)
        {
            @SuppressWarnings("unchecked")
            List<AnimationAccessor<? extends StaticAnimation>> motions = (List<AnimationAccessor<? extends StaticAnimation>>)this.getGuardMotionMap(blockType).getOrDefault(itemCapability.getWeaponCategory(), (a, b) -> null).apply(itemCapability, playerpatch);

            if (motions != null) {
                int motionCounter = dataManager.getDataValue(EpicFightSkillDataKeys.PARRY_MOTION_COUNTER);
                motionCounter %= motions.size();
                result = motions.get(motionCounter);
            }
        }
        dataManager.setDataSyncF(EpicFightSkillDataKeys.PARRY_MOTION_COUNTER, (v) -> v + 1);
        return result != null ? result : super.getGuardMotion(container, playerpatch, itemCapability, blockType);
	}

public AttackResult tryHurt(DamageSource damageSource, float amount) {
        TakeDamageEvent.Income takeDamageEvent$income = new TakeDamageEvent.Income(this, damageSource, amount);
        EpicFightEventHooks.Entity.TAKE_DAMAGE_INCOME.postWithListener(takeDamageEvent$income, this.getEventListener());

        if (takeDamageEvent$income.isCanceled()) {
            return new AttackResult(ResultType.MISSED, takeDamageEvent$income.getDamage());
        } else {
            return AttackResult.of(this.getEntityState().attackResult(damageSource), amount);
        }
    }

@Override
    public void onInitiate(SkillContainer skillContainer, EntityEventListener eventListener) {
        super.onInitiate(skillContainer, eventListener);

        eventListener.registerEvent(
            EpicFightEventHooks.Entity.TAKE_DAMAGE_PRE,
            event -> {
                if (skillContainer.getExecutor().getEntityState().getLevel() == 1 && event.getDamageSource().getEntity() != null && skillContainer.getExecutor().consumeForSkill(this, this.resource)) {
                    float staminaConsumption = Math.max(skillContainer.getExecutor().getStamina() * this.staminaRatio, 1.5F);

                    if (skillContainer.getExecutor().consumeForSkill(this, Skill.Resource.STAMINA, staminaConsumption)) {
                        CompoundTag argument = new CompoundTag();
                        argument.putFloat("staminaConsumption", staminaConsumption);
                        this.executeOnServer(skillContainer, argument);
                    }
                }
            },
            this
        );
    }

@Override
    public void executeOnServer(SkillContainer container, CompoundTag arguments) {
        super.executeOnServer(container, arguments);

        float staminaConsume = arguments.getFloat("staminaConsumption");
        container.getExecutor().setMaxStunShield(staminaConsume);
        container.getExecutor().setStunShield(staminaConsume);

        Player player = container.getExecutor().getOriginal();
        player.level().playSound(null, player.getX(), player.getY(), player.getZ(), EpicFightSounds.ENDURACNE.get(), player.getSoundSource(), 1.0F, 1.0F);

        SPEntityPairingPacket pairingPacket = new SPEntityPairingPacket(container.getExecutor().getOriginal().getId(), EntityPairingPacketTypes.FLASH_WHITE);

        // durationTick, maxOverlay, maxBrightness
        pairingPacket.buffer().writeInt(9);
        pairingPacket.buffer().writeInt(15);
        pairingPacket.buffer().writeInt(1);
        pairingPacket.buffer().writeBoolean(true);

        EpicFightNetworkManager.sendToAllPlayerTrackingThisEntityWithSelf(pairingPacket, container.getServerExecutor().getOriginal());
    }

@Override
    public void cancelOnServer(SkillContainer container, CompoundTag arguments) {
        container.getExecutor().setStunShield(0.0F);
        container.getExecutor().setMaxStunShield(0.0F);

        super.cancelOnServer(container, arguments);
    }

public void executeOnServer(SkillContainer container, CompoundTag args) {
		SPSkillFeedback feedbackPacket = SPSkillFeedback.executed(container.getSlot());
		ServerPlayerPatch executor = container.getServerExecutor();

		if (executor.isHoldingAny()) {
			if (executor.getHoldingSkill() instanceof ChargeableSkill) {
				feedbackPacket.arguments().putInt("chargingTicks", executor.getAccumulatedChargeTicks());
			}

			if (executor.getHoldingSkill() == this) {
				executor.getHoldingSkill().onStopHolding(container, feedbackPacket);
			}

			executor.resetHolding();
		} else {
			container.activate();
		}

		EpicFightNetworkManager.sendToPlayer(feedbackPacket, executor.getOriginal());
	}

public void cancelOnServer(SkillContainer container, CompoundTag args) {
		ServerPlayerPatch executor = container.getServerExecutor();
		SkillCancelEvent skillCancelEvent = new SkillCancelEvent(executor, container);
        EpicFightEventHooks.Player.CANCEL_SKILL.postWithListener(skillCancelEvent, executor.getEventListener());
		EpicFightNetworkManager.sendToPlayer(SPSkillFeedback.expired(container.getSlot()), executor.getOriginal());
	}

public void updateContainer(SkillContainer container) {
		container.prevResource = container.resource;
		container.prevDuration = container.duration;

		if (this.resource == Resource.COOLDOWN) {
			if (container.stack < this.maxStackSize) {
				container.setResource(container.resource + this.getCooldownRegenPerSecond(container.getExecutor()) * EpicFightSharedConstants.A_TICK);
			}
		}

		if (container.isActivated()) {
			if (this.activateType == ActivateType.DURATION) {
				container.duration--;
			}

			boolean isEnd = false;

			if (this.activateType == ActivateType.TOGGLE) {
				if (container.stack <= 0 && !container.getExecutor().getOriginal().isCreative()) {
					isEnd = true;
				}
			} else if (this.activateType != ActivateType.HELD) {
				if (container.duration <= 0) {
					isEnd = true;
				}
			}

			if (isEnd) {
				container.runOnServer(serverplayerpatch -> {
                    this.cancelOnServer(container, null);
				});

				container.deactivate();
			}
		}

		if (this.activateType == ActivateType.HELD && container.getExecutor().getHoldingSkill() == this) {
			HoldableSkill holdableSkill = (HoldableSkill)this;
			holdableSkill.holdTick(container);

			container.runOnServer(serverExecutor -> {
				container.getExecutor().resetActionTick();

				if (this instanceof ChargeableSkill chargingSkill && container.getExecutor().getSkillChargingTicks(1.0F) > chargingSkill.getAllowedMaxChargingTicks()) {
					SPSkillFeedback feedbackPacket = SPSkillFeedback.executed(container.getSlot());
					feedbackPacket.arguments().putInt("chargingTicks", serverExecutor.getAccumulatedChargeTicks());
					chargingSkill.onStopHolding(container, feedbackPacket);
					container.getExecutor().resetHolding();
					EpicFightNetworkManager.sendToPlayer(feedbackPacket, serverExecutor.getOriginal());
				}
			});
		}
	}

public void activate() {
        if (!this.isActivated) {
            this.prevDuration = this.maxDuration;
            this.duration = this.maxDuration;
            this.isActivated = true;
        }
    }

public void deactivate() {
        if (this.isActivated) {
            this.prevDuration = 0;
            this.duration = 0;
            this.isActivated = false;
        }
    }

@Override
    public void onInitiate(SkillContainer container, EntityEventListener eventListener) {
        super.onInitiate(container, eventListener);

        eventListener.registerEvent(
            EpicFightEventHooks.Player.CAST_SKILL,
            event -> {
                if (event.getSkillContainer().getSkill().getCategory() == SkillCategories.DODGE) {
                    EntityState state = container.getExecutor().getEntityState();
                    DynamicAnimation animation = container.getExecutor().getAnimator().getPlayerFor(null).getRealAnimation().get();

                    if (
                        (
                            !event.isStateExecutable() && animation instanceof AttackAnimation &&
                                    this.isAvailableCategory(container.getExecutor().getPrimaryItemCapability())
                        ) ||
                        (
                            state.hurt() &&
                            container.getStack() > 0
                        )
                    ) {
                        event.setStateExecutable(true);
                    }
                }
            },
            this
        );

        eventListener.registerEvent(
            EpicFightEventHooks.Player.CONSUME_SKILL,
            event -> {
                if (event.getSkill().getCategory() == SkillCategories.DODGE) {
                    if (!container.getExecutor().getOriginal().isCreative()) {
                        if (event.getSkill().getConsumption() > container.getExecutor().getStamina()) {
                            if (container.getExecutor().consumeForSkill(this, this.resource)) {
                                if (!container.getExecutor().isLogicalClient()) {
                                    this.executeOnServer(container, event.getArguments());
                                }

                                event.setResourceType(Skill.Resource.NONE);
                            }
                        } else if (container.getExecutor().getEntityState().hurt() && container.getExecutor().consumeForSkill(this, this.resource)) {
                            if (!container.getExecutor().isLogicalClient()) {
                                this.executeOnServer(container, event.getArguments());
                            }
                        }
                    }
                }
            },
            this
        );
    }

@Override
    public void executeOnServer(SkillContainer container, CompoundTag arguments) {
        this.setStackSynchronize(container, container.getStack() - 1);
        float yRot = container.getExecutor().getYRot();

        if (arguments.contains("yRot")) {
            yRot = arguments.getFloat("yRot");
        }

        container.getExecutor().playSound(EpicFightSounds.EMERGENCY_ESCAPE.get(), 1.0F, 1.0F);

        SPEntityPairingPacket pairingPacket = new SPEntityPairingPacket(container.getExecutor().getOriginal().getId(), EntityPairingPacketTypes.EMERGENCY_ESCAPE_ACTIVATED);
        pairingPacket.buffer().writeFloat(yRot);

        EpicFightNetworkManager.sendToAllPlayerTrackingThisEntityWithSelf(pairingPacket, container.getServerExecutor().getOriginal());
    }

public boolean canUse(PlayerPatch<?> executor, SkillCastEvent event) {
        if (this.skill == null) {
            return false;
        } else {
            if (executor.isHoldingSkill(this.skill) && this.skill instanceof ChargeableSkill chargingSkill) {
                if (executor.isLogicalClient()) {
                    return true;
                } else {
                    return executor.getSkillChargingTicks() >= chargingSkill.getMinChargingTicks();
                }
            }

            event.setSkillExecutable(this.skill.canExecute(this));
            event.setStateExecutable(this.skill.isExecutableState(executor));

            EpicFightEventHooks.Player.CAST_SKILL.postWithListener(event, executor.getEventListener());

            if (!event.isCanceled() && event.isExecutable()) {
                return (executor.getOriginal().isCreative() || this.skill.resourcePredicate(executor, event)) || (this.isActivated() && this.skill.activateType == ActivateType.DURATION);
            } else {
                return false;
            }
        }
    }

public boolean requestCasting(ServerPlayerPatch executor, CompoundTag args) {
        SkillCastEvent event = new SkillCastEvent(executor, this, args);

        if (this.canUse(executor, event)) {
            this.skill.executeOnServer(this, event.getArguments());
            return true;
        }

        return false;
    }

public void updateContainer(SkillContainer container) {
		container.prevResource = container.resource;
		container.prevDuration = container.duration;

		if (this.resource == Resource.COOLDOWN) {
			if (container.stack < this.maxStackSize) {
				container.setResource(container.resource + this.getCooldownRegenPerSecond(container.getExecutor()) * EpicFightSharedConstants.A_TICK);
			}
		}

		if (container.isActivated()) {
			if (this.activateType == ActivateType.DURATION) {
				container.duration--;
			}

			boolean isEnd = false;

			if (this.activateType == ActivateType.TOGGLE) {
				if (container.stack <= 0 && !container.getExecutor().getOriginal().isCreative()) {
					isEnd = true;
				}
			} else if (this.activateType != ActivateType.HELD) {
				if (container.duration <= 0) {
					isEnd = true;
				}
			}

			if (isEnd) {
				container.runOnServer(serverplayerpatch -> {
                    this.cancelOnServer(container, null);
				});

				container.deactivate();
			}
		}

		if (this.activateType == ActivateType.HELD && container.getExecutor().getHoldingSkill() == this) {
			HoldableSkill holdableSkill = (HoldableSkill)this;
			holdableSkill.holdTick(container);

			container.runOnServer(serverExecutor -> {
				container.getExecutor().resetActionTick();

				if (this instanceof ChargeableSkill chargingSkill && container.getExecutor().getSkillChargingTicks(1.0F) > chargingSkill.getAllowedMaxChargingTicks()) {
					SPSkillFeedback feedbackPacket = SPSkillFeedback.executed(container.getSlot());
					feedbackPacket.arguments().putInt("chargingTicks", serverExecutor.getAccumulatedChargeTicks());
					chargingSkill.onStopHolding(container, feedbackPacket);
					container.getExecutor().resetHolding();
					EpicFightNetworkManager.sendToPlayer(feedbackPacket, serverExecutor.getOriginal());
				}
			});
		}
	}

@Override
    public void onInitiate(SkillContainer container, EntityEventListener eventListener) {
        super.onInitiate(container, eventListener);

        eventListener.registerEvent(
            EpicFightEventHooks.Entity.TAKE_DAMAGE_PRE,
            event -> {
                if (event.getDamageSource().getEntity() == null) {
                    return;
                }

                int currentTargetId = container.getDataManager().getDataValue(EpicFightSkillDataKeys.ENTITY_ID);

                if (currentTargetId == -1 && event.getDamageSource().getEntity() instanceof LivingEntity livingentity) {
                    setNewTarget(container, livingentity);
                } else if (currentTargetId == event.getDamageSource().getEntity().getId()) {
                    container.getDataManager().setDataSync(EpicFightSkillDataKeys.TICK_RECORD, container.getExecutor().getOriginal().tickCount);
                } else if (currentTargetId != event.getDamageSource().getEntity().getId() && event.getDamageSource().getEntity() instanceof LivingEntity livingentity) {
                    if (canResetTarget(container)) {
                        setNewTarget(container, livingentity);
                    }
                }
            },
            this
        );

        eventListener.registerEvent(
            EpicFightEventHooks.Entity.DELIVER_DAMAGE_PRE,
            event -> {
                int currentTargetId = container.getDataManager().getDataValue(EpicFightSkillDataKeys.ENTITY_ID);

                if (currentTargetId == event.getTarget().getId()) {
                    event.getDamageSource().attachDamageModifier(ValueModifier.multiplier(1.0F + this.damageBonus));
                    container.getDataManager().setDataSync(EpicFightSkillDataKeys.TICK_RECORD, container.getExecutor().getOriginal().tickCount);
                } else if (container.isActivated()) {
                    float f = this.damageBonus * container.getDurationRatio(1.0F);
                    event.getDamageSource().attachDamageModifier(ValueModifier.multiplier(1.0F + f));
                }
            },
            this
        );

        eventListener.registerEvent(
            EpicFightEventHooks.Entity.KILL_ENTITY,
            event -> {
                if (container.isActivated()) {
                    return;
                }

                int currentTargetId = container.getDataManager().getDataValue(EpicFightSkillDataKeys.ENTITY_ID);

                if (currentTargetId == event.getKilledEntity().getId()) {
                    this.executeOnServer(container, null);
                    container.getDataManager().setDataSync(EpicFightSkillDataKeys.ENTITY_ID, -1);
                }
            },
            this
        );
    }

@Override
    public void onRemoved(SkillContainer container) {
