public static void tickPlayer(ServerPlayerEntity player) {
        if (player == null) {
            return;
        }

        Iterator<Map.Entry<ChannelKey, ActiveChannel>> iterator = ACTIVE_CHANNELS.entrySet().iterator();
        while (iterator.hasNext()) {
            Map.Entry<ChannelKey, ActiveChannel> entry = iterator.next();
            ChannelKey key = entry.getKey();
            if (!key.playerUuid.equals(player.getUuid())) {
                continue;
            }

            ActiveChannel channel = entry.getValue();
            if (channel.finished) {
                iterator.remove();
                continue;
            }

            if (!isValid(player, channel)) {
                iterator.remove();
                continue;
            }

            int remainingUseTicks = remainingUseTicks(player, channel);
            if (remainingUseTicks <= 0) {
                iterator.remove();
                finish(player, channel);
                continue;
            }

            if (isVanillaChanneling(player, channel)) {
                continue;
            }

            ItemStack currentStack = player.getStackInHand(channel.hand);
            currentStack.usageTick(player.getWorld(), player, remainingUseTicks);
            if (channel.finished) {
                iterator.remove();
            }
        }
    }

public static void start(ServerPlayerEntity player, Hand hand, ItemStack stack) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        if (player == null || hand == null || stack == null || stack.isEmpty()) {
            return;
        }

        int maxUseTime = stack.getMaxUseTime(player);
        if (maxUseTime <= 0) {
            return;
        }

        ActiveChannel channel = new ActiveChannel(hand, stack.copy(), player.getWorld().getRegistryKey(),
                player.getWorld().getTime(), maxUseTime);
        ACTIVE_CHANNELS.put(new ChannelKey(player.getUuid(), hand), channel);
        }
    }

public static boolean stop(ServerPlayerEntity player, Hand hand) {
        if (player == null || hand == null) {
            return false;
        }

        ActiveChannel channel = ACTIVE_CHANNELS.remove(new ChannelKey(player.getUuid(), hand));
        if (channel == null) {
            return false;
        }

        if (channel.finished) {
            return true;
        }

        finish(player, channel);
        return true;
    }

public static boolean finishEarly(ServerPlayerEntity player, ItemStack stack) {
        if (player == null || stack == null || stack.isEmpty()) {
            return false;
        }

        for (Hand hand : Hand.values()) {
            ChannelKey key = new ChannelKey(player.getUuid(), hand);
            ActiveChannel channel = ACTIVE_CHANNELS.get(key);
            if (channel != null
                    && ItemStack.areItemsEqual(channel.stack, stack)
                    && ItemStack.areItemsEqual(player.getStackInHand(hand), stack)) {
                if (!channel.finished) {
                    finish(player, channel);
                }
                channel.finished = true;
                return true;
            }
        }

        return false;
    }

private static boolean isValid(ServerPlayerEntity player, ActiveChannel channel) {
        if (!player.isAlive() || player.getWorld().isClient()
                || IncapacitatingStatusEffectRegistry.isIncapacitated(player)
                || player.getWorld().getRegistryKey() != channel.worldKey) {
            return false;
        }

        ItemStack currentStack = player.getStackInHand(channel.hand);
        return !currentStack.isEmpty()
                && ItemStack.areItemsEqual(currentStack, channel.stack)
                && currentStack.getDamage() < currentStack.getMaxDamage() - 1;
    }

private static void finish(ServerPlayerEntity player, ActiveChannel channel) {
        if (!isValid(player, channel)) {
            return;
        }

        ItemStack currentStack = player.getStackInHand(channel.hand);
        int remainingUseTicks = Math.max(0, remainingUseTicks(player, channel));
        currentStack.onStoppedUsing(player.getWorld(), player, remainingUseTicks);

        if (player.isUsingItem() && player.getActiveHand() == channel.hand) {
            player.clearActiveItem();
        }
    }

private static int remainingUseTicks(ServerPlayerEntity player, ActiveChannel channel) {
        long elapsed = Math.max(0L, player.getWorld().getTime() - channel.startedAt);
        return (int) Math.max(0L, channel.maxUseTime - elapsed);
    }

private static boolean isVanillaChanneling(ServerPlayerEntity player, ActiveChannel channel) {
        return player.isUsingItem()
                && player.getActiveHand() == channel.hand
                && ItemStack.areItemsEqual(player.getStackInHand(channel.hand), channel.stack);
    }

public static void handleInput(ServerPlayerEntity player, Hand hand, boolean pressed) {
        if (player == null || hand == null || !player.isAlive()) {
            return;
        }
        if (pressed) {
            start(player, hand);
        } else {
            stop(player, hand);
        }
    }

public static boolean start(ServerPlayerEntity player, Hand hand) {
        ItemStack stack = player.getStackInHand(hand);
        if (!canUseBeforeCooldown(player, stack)) {
            return false;
        }

        if (stack.getItem() instanceof UniqueWeaponActiveAbility) {
            if (AwakeningApi.isAbilityUnlocked(stack)
                    && stack.getItem() instanceof UniqueWeaponSecondaryAction secondaryAction) {
                TypedActionResult<ItemStack> secondary = secondaryAction.startPlayerSecondaryAbility(
                        player.getWorld(), player, hand);
                if (secondary.getResult() != ActionResult.PASS) {
                    return secondary.getResult().isAccepted();
                }
            }
            if (player.getItemCooldownManager().isCoolingDown(stack.getItem())) {
                return false;
            }
            TypedActionResult<ItemStack> result = ((UniqueWeaponActiveAbility) stack.getItem()).startPlayerAbility(player.getWorld(), player, hand);
            if (result.getResult().isAccepted()) {
                PlayerWeaponAbilityChannelManager.start(player, hand, player.getStackInHand(hand));
                return true;
            }
            return false;
        }

        if (stack.getItem() instanceof RunicSwordItem) {
            GemPowerComponent component = SimplySwordsAPI.getComponent(stack);
            if (!component.isEmpty()) {
                TypedActionResult<ItemStack> result = component.use(player.getWorld(), player, hand);
                if (result.getResult().isAccepted()) {
                    PlayerWeaponAbilityChannelManager.start(player, hand, player.getStackInHand(hand));
                    player.swingHand(hand, true);
                    return true;
                }
            }
        }

        return false;
    }

public static void stop(ServerPlayerEntity player, Hand hand) {
        if (PlayerWeaponAbilityChannelManager.stop(player, hand)) {
            return;
        }

        ItemStack stack = player.getStackInHand(hand);
        if (!stack.isEmpty() && player.isUsingItem() && player.getActiveHand() == hand) {
            stack.onStoppedUsing(player.getWorld(), player, player.getItemUseTimeLeft());
            player.clearActiveItem();
        }
    }

private static boolean activateWeaponWithProvenance(WeaponAbilityContext context) {
        if (context == null
                || context.stack() == null
                || context.stack().isEmpty()
                || context.actor() == null
                || WaxweaverEncasementManager.isEncased(context.actor())
                || IncapacitatingStatusEffectRegistry.isIncapacitated(context.actor())
                || !AwakeningApi.isAbilityUnlocked(context.stack())
                || !(context.stack().getItem() instanceof UniqueWeaponActiveAbility ability)
                || !ability.canActivate(context)) {
            return false;
        }

        if (isWeaponAbilityCoolingDown(context)) {
            return false;
        }

        UniqueAbilityApi.clearStartedExecution();
        boolean activated;
        try {
            activated = ability.activate(context);
        } catch (RuntimeException exception) {
            UniqueAbilityExecution failedExecution = UniqueAbilityApi.takeStartedExecution();
            if (failedExecution != null) {
                UniqueAbilityApi.cancel(failedExecution);
            }
            throw exception;
        }
        UniqueAbilityExecution execution = UniqueAbilityApi.takeStartedExecution();
        if (!activated) {
            if (execution != null) {
                UniqueAbilityApi.cancel(execution);
            }
            return false;
        }

        int cooldown = ability.getActivationCooldownTicks(context.stack(), context);
        if (execution != null) {
            UniqueAbilityApi.start(execution);
            cooldown = execution.cooldownTicks(cooldown);
        }
        setWeaponCooldown(context.actor(), context.stack(), cooldown);
        if (execution != null) {
            double fraction = execution.takeCooldownRefundFraction();
            if (fraction > 0) {
                int remaining = getRemainingWeaponCooldownTicks(context.actor(), context.stack());
                reduceWeaponCooldown(context.actor(), context.stack(), remaining,
                        (int) Math.round(remaining * fraction));
            }
        }
        return true;
    }

public static boolean tryActivateWeaponAbility(WeaponAbilityContext context) {
        if (context == null) return false;
        try (var ignored = CombatProvenanceApi.origin(
                context.actor(), context.stack(), CombatProvenance.ABILITY)) {
            return activateWeaponWithProvenance(context);
        }
    }

public static void setWeaponCooldown(LivingEntity actor, ItemStack stack, int baseCooldownTicks) {
        if (actor == null || stack == null || stack.isEmpty() || baseCooldownTicks < 0) {
            return;
        }
        if (baseCooldownTicks == 0) {
            if (actor instanceof PlayerEntity player) {
                player.getItemCooldownManager().set(stack.getItem(), 0);
            } else {
                WeaponAbilityCooldownManager.clearCooldown(actor, stack);
            }
            return;
        }

        int cooldown = getEffectiveWeaponCooldownTicks(stack, actor, baseCooldownTicks);
        if (actor instanceof PlayerEntity player) {
            player.getItemCooldownManager().set(stack.getItem(), cooldown);
        } else if (actor.getWorld() instanceof ServerWorld world) {
            WeaponAbilityCooldownManager.setCooldown(world, actor, stack, cooldown);
        }
    }

private static boolean isWeaponAbilityCoolingDown(WeaponAbilityContext context) {
        if (context == null || context.stack() == null || context.stack().isEmpty() || context.actor() == null) {
            return true;
        }
        if (context.actor() instanceof ServerPlayerEntity player) {
            return player.getItemCooldownManager().isCoolingDown(context.stack().getItem());
        }
        return context.world() == null || WeaponAbilityCooldownManager.isCoolingDown(context.world(), context.actor(), context.stack());
    }

public static void reduceWeaponCooldown(LivingEntity actor, ItemStack stack,
                                            int totalCooldownTicks, int reductionTicks) {
        if (actor == null || stack == null || stack.isEmpty()
                || totalCooldownTicks <= 0 || reductionTicks <= 0) {
            return;
        }
        if (actor instanceof PlayerEntity player) {
            ItemCooldownManagerAccessor cooldownManager =
                    (ItemCooldownManagerAccessor) player.getItemCooldownManager();
            Object entry = cooldownManager.simplyswords$getEntries().get(stack.getItem());
            int remaining = entry instanceof ItemCooldownEntryAccessor cooldownEntry
                    ? Math.max(0, cooldownEntry.simplyswords$getEndTick() - cooldownManager.simplyswords$getTick())
                    : 0;
            if (remaining <= 0) {
                return;
            }
            player.getItemCooldownManager().set(stack.getItem(), Math.max(0, remaining - reductionTicks));
        } else if (actor.getWorld() instanceof ServerWorld world) {
            WeaponAbilityCooldownManager.reduceCooldown(world, actor, stack, reductionTicks);
        }
    }

private static int getRemainingWeaponCooldownTicks(LivingEntity actor, ItemStack stack) {
        if (actor instanceof PlayerEntity player) {
            ItemCooldownManagerAccessor manager = (ItemCooldownManagerAccessor) player.getItemCooldownManager();
            Object entry = manager.simplyswords$getEntries().get(stack.getItem());
            return entry instanceof ItemCooldownEntryAccessor cooldown
                    ? Math.max(0, cooldown.simplyswords$getEndTick() - manager.simplyswords$getTick()) : 0;
        }
        return actor.getWorld() instanceof ServerWorld world
                ? WeaponAbilityCooldownManager.remainingTicks(world, actor, stack) : 0;
    }

public static int getEffectiveWeaponCooldownTicks(ItemStack stack, LivingEntity actor, int baseCooldownTicks) {
        if (baseCooldownTicks <= 0) {
            return 0;
        }

        int cooldown = Math.max(1, baseCooldownTicks);
        if (stack == null || stack.isEmpty() || actor == null
                || !Config.compatibility.ironsSpells.get().enableCooldownReduction.get()) {
            return cooldown;
        }
        if (stack.getItem() instanceof UniqueWeaponActiveAbility ability
                && !ability.usesSpellCooldownReduction(stack)) {
            return cooldown;
        }
        return Math.max(1, SimplySwordsExpectPlatform.applySpellCooldownReduction(cooldown, actor));
    }

public static boolean isCoolingDown(ServerWorld world, LivingEntity actor, ItemStack stack) {
        if (actor == null || stack == null || stack.isEmpty()) {
            return true;
        }
        return COOLDOWNS.getOrDefault(new CooldownKey(actor.getUuid(), stack.getItem()), 0L) > world.getTime();
    }

public static void setCooldown(ServerWorld world, LivingEntity actor, ItemStack stack, int cooldownTicks) {
        if (actor == null || stack == null || stack.isEmpty() || cooldownTicks <= 0) {
            return;
        }
        COOLDOWNS.put(new CooldownKey(actor.getUuid(), stack.getItem()), world.getTime() + cooldownTicks);
    }

public static void reduceCooldown(ServerWorld world, LivingEntity actor, ItemStack stack, int ticks) {
        if (actor == null || stack == null || stack.isEmpty() || ticks <= 0) {
            return;
        }
        CooldownKey key = new CooldownKey(actor.getUuid(), stack.getItem());
        Long endTick = COOLDOWNS.get(key);
        if (endTick == null) {
            return;
        }
        long reduced = reducedEndTick(endTick, world.getTime(), ticks);
        if (reduced <= world.getTime()) COOLDOWNS.remove(key);
        else COOLDOWNS.put(key, reduced);
    }

static long reducedEndTick(long endTick, long now, int ticks) {
        if (endTick <= now || ticks <= 0) {
            return endTick;
        }
        return Math.max(now, endTick - ticks);
    }

public static void tick(ServerWorld world) {
        if (world.getTime() % 200L != 0L) {
            return;
        }
        long now = world.getTime();
        Iterator<Map.Entry<CooldownKey, Long>> iterator = COOLDOWNS.entrySet().iterator();
        while (iterator.hasNext()) {
            Map.Entry<CooldownKey, Long> entry = iterator.next();
            if (entry.getValue() <= now) {
                iterator.remove();
            }
        }
    }

public static void tick(ServerWorld world) {
        long now = world.getTime();
        if (now % 200L == 0L) {
            purgeCooldowns(world, now);
        }

        List<PendingStrike> strikes = PENDING_STRIKES.get(world);
        if (strikes == null || strikes.isEmpty()) {
            PENDING_STRIKES.remove(world);
            return;
        }

        Iterator<PendingStrike> iterator = strikes.iterator();
        while (iterator.hasNext()) {
            PendingStrike strike = iterator.next();
            if (now < strike.executeTick()) {
                continue;
            }
            iterator.remove();
            executeStrike(world, strike);
        }

        if (strikes.isEmpty()) {
            PENDING_STRIKES.remove(world);
        }
    }

public static void tryStrikeNearby(LivingEntity owner, ItemStack stack) {
        if (owner == null
                || stack == null
                || stack.isEmpty()
                || !(owner.getWorld() instanceof ServerWorld world)
                || !owner.isAlive()) {
            return;
        }

        double range = Math.max(0.5, Config.gemPowers.evocation.range);
        Box searchBox = owner.getBoundingBox().expand(range, Math.max(2.0, range * 0.5), range);
        List<LivingEntity> targets = world.getEntitiesByClass(LivingEntity.class, searchBox, target ->
                        isValidTarget(owner, target) && isTargetReady(world, target))
                .stream()
                .sorted(Comparator.comparingDouble(owner::squaredDistanceTo))
                .limit(Math.max(1, Config.gemPowers.evocation.maxTargetsPerScan))
                .toList();

        if (targets.isEmpty()) {
            return;
        }

        float damage = HelperMethods.gemPowerScaledDamage(SpellScalingComponents.power("evocation"), owner, stack,
                Config.gemPowers.evocation.damageScaling,
                Config.gemPowers.evocation.spellScaling);
        if (damage <= 0.0F) {
            return;
        }

        long now = world.getTime();
        for (LivingEntity target : targets) {
            markTargetCooldown(world, target, now);
            spawnFangs(world, owner, target);
            scheduleStrike(world, owner, target, stack, damage, now);
        }

        world.playSound(null, owner.getX(), owner.getY(), owner.getZ(),
                SoundEvents.ENTITY_EVOKER_CAST_SPELL, SoundCategory.PLAYERS, 0.5F, 0.85F + world.random.nextFloat() * 0.12F);
    }

private static boolean isValidTarget(LivingEntity owner, LivingEntity target) {
        return target != null
                && target != owner
                && target.isAlive()
                && EntityPredicates.VALID_LIVING_ENTITY.test(target)
                && HelperMethods.checkFriendlyFire(target, owner);
    }

private static boolean isTargetReady(ServerWorld world, LivingEntity target) {
        Map<UUID, Long> cooldowns = TARGET_COOLDOWNS.get(world);
        if (cooldowns == null) {
            return true;
        }
        Long lastStrike = cooldowns.get(target.getUuid());
        return lastStrike == null || world.getTime() - lastStrike >= Math.max(1, Config.gemPowers.evocation.targetCooldownTicks);
    }

private static void markTargetCooldown(ServerWorld world, LivingEntity target, long now) {
        TARGET_COOLDOWNS.computeIfAbsent(world, ignored -> new HashMap<>()).put(target.getUuid(), now);
    }

private static void scheduleStrike(ServerWorld world, LivingEntity owner, LivingEntity target, ItemStack stack, float damage, long now) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        long executeTick = now + Math.max(0, Config.gemPowers.evocation.fangWarmupTicks)
                + Math.max(0, Config.gemPowers.evocation.damageDelayTicks);
        PENDING_STRIKES.computeIfAbsent(world, ignored -> new ArrayList<>())
                .add(new PendingStrike(owner.getUuid(), target.getUuid(), stack.copy(), damage, executeTick));
        }
    }

private static void spawnFangs(ServerWorld world, LivingEntity owner, LivingEntity target) {
        Vec3d pos = target.getPos();
        float yaw = (float) MathHelper.atan2(target.getZ() - owner.getZ(), target.getX() - owner.getX());
        EvokerFangsEntity fangs = new EvokerFangsEntity(world, pos.x, target.getY(), pos.z, yaw,
                Math.max(0, Config.gemPowers.evocation.fangWarmupTicks), owner);
        fangs.addCommandTag(VISUAL_ONLY_TAG);
        world.spawnEntity(fangs);

        world.spawnParticles(ParticleTypes.SOUL, pos.x, target.getBodyY(0.25), pos.z, 6, 0.35, 0.08, 0.35, 0.02);
        world.playSound(null, pos.x, pos.y, pos.z,
                SoundRegistry.MAGIC_SWORD_SPELL_02.get(), SoundCategory.PLAYERS, 0.35F, 0.75F + world.random.nextFloat() * 0.08F);
    }

private static void executeStrike(ServerWorld world, PendingStrike strike) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(strike == null ? null : CombatProvenanceApi.from(strike.stack(), null))) {
        Entity ownerEntity = world.getEntity(strike.ownerId());
        Entity targetEntity = world.getEntity(strike.targetId());
        if (!(ownerEntity instanceof LivingEntity owner)
                || !(targetEntity instanceof LivingEntity target)
                || !owner.isAlive()
                || !isValidTarget(owner, target)) {
            return;
        }

        boolean damaged = SimplySwordsAPI.applyEntityWeaponHit(strike.stack(), target, owner, strike.damage());
        if (!damaged) {
            return;
        }

        int amplifier = MathHelper.clamp(Config.gemPowers.evocation.slownessAmplifier, 0, 1);
        int duration = AwakeningApi.scaleGemPowerDuration(
                strike.stack(), Math.max(1, Config.gemPowers.evocation.slownessDurationTicks));
        target.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS, duration, amplifier, false, false, true), owner);
        world.spawnParticles(ParticleTypes.ENCHANTED_HIT, target.getX(), target.getBodyY(0.5), target.getZ(), 8, 0.3, 0.3, 0.3, 0.05);
        world.playSound(null, target.getX(), target.getY(), target.getZ(),
                SoundEvents.ENTITY_EVOKER_FANGS_ATTACK, SoundCategory.PLAYERS, 0.8F, 0.9F + world.random.nextFloat() * 0.1F);
        }
    }

private static void purgeCooldowns(ServerWorld world, long now) {
        Map<UUID, Long> cooldowns = TARGET_COOLDOWNS.get(world);
        if (cooldowns == null) {
            return;
        }
        long expiry = Math.max(20L, Config.gemPowers.evocation.targetCooldownTicks * 4L);
        cooldowns.entrySet().removeIf(entry -> now - entry.getValue() > expiry);
        if (cooldowns.isEmpty()) {
            TARGET_COOLDOWNS.remove(world);
        }
    }

@Override
    public void inventoryTick(ItemStack stack, World world, LivingEntity user, int slot, boolean selected) {
        if (world.isClient()) {
            return;
        }

        int frequency = Math.max(1, Config.gemPowers.evocation.scanFrequencyTicks);
        if (user.age % frequency != 0) {
            return;
        }

        EvocationFangManager.tryStrikeNearby(user, stack);
    }

