public static boolean applyEntityWeaponHit(ItemStack stack, LivingEntity target, LivingEntity actor, float damage) {
        if (stack == null || stack.isEmpty() || target == null || actor == null
                || !(actor.getWorld() instanceof ServerWorld world) || target.getWorld() != world
                || !target.isAlive()) {
            return false;
        }
        if (IgnoredEntities.isIgnored(target)) {
            return false;
        }

        Vec3d facing = actor.getRotationVec(1.0F);
        if (facing.lengthSquared() < 0.0001) {
            facing = target.getPos().subtract(actor.getPos());
        }
        if (facing.lengthSquared() < 0.0001) {
            facing = Vec3d.fromPolar(0.0F, actor.getYaw());
        }
        facing = facing.normalize();

        DelegatedWeaponHitContext context = new DelegatedWeaponHitContext(actor instanceof ServerPlayerEntity player ? player : null, actor, actor.getPos(), facing);
        DelegatedWeaponHitContext previousContext = DELEGATED_WEAPON_HIT_CONTEXT.get();
        DELEGATED_WEAPON_HIT_CONTEXT.set(context);
        try (var ignored = CombatProvenanceApi.scope(
                CombatProvenanceApi.from(stack, actor))) {
            DamageSource source = getWeaponDamageSource(actor);
            float modifiedDamage = WeaponImplicitRegistry.modifyDamage(stack, target, source, damage);
            target.timeUntilRegen = 0;
            boolean[] damaged = {false};
            WeaponImplicitRegistry.runSuppressed(() -> damaged[0] = target.damage(source, modifiedDamage));
            target.timeUntilRegen = 0;
            if (!damaged[0]) {
                return false;
            }

            EnchantmentHelper.onTargetDamaged(world, target, source, stack);
            WeaponImplicitRegistry.onHit(stack, target, actor, modifiedDamage);
            Item item = stack.getItem();
            if (item instanceof SwordItem) {
                NecromanticArsenalPower.runSuppressed(() -> item.postHit(stack, target, actor));
            }
            return true;
        } finally {
            if (previousContext == null) DELEGATED_WEAPON_HIT_CONTEXT.remove();
            else DELEGATED_WEAPON_HIT_CONTEXT.set(previousContext);
        }
    }

public static void tryFire(ServerWorld world, LivingEntity user, ItemStack stack) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        if (world == null || user == null || stack == null || stack.isEmpty() || isSuppressed() || !user.isAlive()) {
            return;
        }

        if (!IGNORE_ATTACK_READY.get() && !isAttackReady(world, user, stack)) {
            return;
        }

        Vec3d direction = user.getRotationVec(1.0F);
        if (direction.lengthSquared() < 0.0001) {
            direction = Vec3d.fromPolar(user.getPitch(), user.getYaw());
        }
        if (direction.lengthSquared() < 0.0001) {
            return;
        }
        direction = direction.normalize();

        double speed = Math.max(0.05, Config.gemPowers.runicSlash.speed);
        double distance = Math.max(0.25, Config.gemPowers.runicSlash.distance);
        float damage = HelperMethods.gemPowerScaledDamage(SpellScalingComponents.power("runic_slash"), user, stack,
                Config.gemPowers.runicSlash.damageScaling,
                Config.gemPowers.runicSlash.spellScaling);
        Vec3d start = user.getEyePos().subtract(0.0, Math.max(0.15, user.getHeight() * 0.18), 0.0).add(direction.multiply(0.65));

        RunicSlashProjectileEntity slash = new RunicSlashProjectileEntity(world, user, stack.copy(), direction, distance, speed, damage, Config.gemPowers.runicSlash.width);
        slash.setPosition(start);
        slash.setYaw(user.getYaw());
        slash.setPitch(user.getPitch());
        world.spawnEntity(slash);

        world.playSound(null, user.getX(), user.getY(), user.getZ(), SoundRegistry.SWING_WOOSH.get(), SoundCategory.PLAYERS, 0.75F, 1.25F + world.random.nextFloat() * 0.12F);
        world.playSound(null, user.getX(), user.getY(), user.getZ(), SoundRegistry.ELEMENTAL_SWORD_WIND_ATTACK_03.get(), SoundCategory.PLAYERS, 0.45F, 1.45F + world.random.nextFloat() * 0.12F);
        world.spawnParticles(ParticleTypes.SWEEP_ATTACK, start.x, start.y, start.z, 1, 0.0, 0.0, 0.0, 0.0);
        }
    }

private static boolean isAttackReady(ServerWorld world, LivingEntity user, ItemStack stack) {
        long now = world.getTime();
        if (now % 200L == 0L) {
            purgeOldEntries(now);
        }
        Long nextEligible = LAST_ACTIVATION.get(user.getUuid());
        if (nextEligible != null && now < nextEligible) {
            return false;
        }
        LAST_ACTIVATION.put(user.getUuid(), now + SimplySwordsAPI.getEffectiveWeaponCooldownTicks(
                stack, user, getAttackReadyCooldownTicks(user)));
        return true;
    }

private static int getAttackReadyCooldownTicks(LivingEntity user) {
        EntityAttributeInstance attackSpeedAttribute = user.getAttributeInstance(EntityAttributes.GENERIC_ATTACK_SPEED);
        double attackSpeed = attackSpeedAttribute != null ? attackSpeedAttribute.getValue() : 4.0;
        if (attackSpeed <= 0.0) {
            attackSpeed = 4.0;
        }
        return Math.max(Config.gemPowers.runicSlash.minimumSwingCooldownTicks, (int) Math.ceil(20.0 / attackSpeed));
    }

private static void purgeOldEntries(long now) {
        Iterator<Map.Entry<UUID, Long>> iterator = LAST_ACTIVATION.entrySet().iterator();
        while (iterator.hasNext()) {
            if (iterator.next().getValue() <= now) {
                iterator.remove();
            }
        }
    }

public static void runSuppressed(Runnable runnable) {
        SUPPRESSED.set(true);
        try {
            runnable.run();
        } finally {
            SUPPRESSED.set(false);
        }
    }

public static void runIgnoringAttackReady(Runnable runnable) {
        boolean previous = IGNORE_ATTACK_READY.get();
        IGNORE_ATTACK_READY.set(true);
        try {
            runnable.run();
        } finally {
            IGNORE_ATTACK_READY.set(previous);
        }
    }

@Override
    public void tick() {
        super.tick();
        if (this.getWorld().isClient()) {
            return;
        }

        if (!(this.getWorld() instanceof ServerWorld world) || !(getOwnerEntity(world) instanceof LivingEntity owner) || !owner.isAlive()) {
            this.discard();
            return;
        }

        Vec3d current = this.getPos();
        Vec3d velocity = this.getVelocity();
        if (velocity.lengthSquared() < 0.0001) {
            this.discard();
            return;
        }

        Vec3d next = current.add(velocity);
        BlockHitResult blockHit = world.raycast(new RaycastContext(current, next, RaycastContext.ShapeType.COLLIDER, RaycastContext.FluidHandling.NONE, this));
        if (blockHit.getType() != HitResult.Type.MISS) {
            next = blockHit.getPos();
        }

        damageTargets(world, owner, current, next);
        spawnTrail(world, current, next);

        this.traveled += current.distanceTo(next);
        this.setPosition(next);
        if (blockHit.getType() != HitResult.Type.MISS || this.traveled >= this.maxDistance || this.age > 80) {
            this.discard();
        }
    }

private void damageTargets(ServerWorld world, LivingEntity owner, Vec3d current, Vec3d next) {
        ItemStack stack = this.dataTracker.get(WEAPON_STACK);
        if (stack.isEmpty()) {
            return;
        }

        double halfWidth = Math.max(0.1, this.dataTracker.get(WIDTH) * 0.5F);
        Box searchBox = new Box(current, next).expand(halfWidth);
        for (Entity entity : world.getOtherEntities(this, searchBox, entity -> entity instanceof LivingEntity && entity.isAlive())) {
            if (!(entity instanceof LivingEntity target)
                    || target == owner
                    || this.hitTargets.contains(target.getUuid())
                    || !target.getBoundingBox().expand(target.getTargetingMargin()).expand(halfWidth * 0.35).intersects(searchBox)
                    || !HelperMethods.checkAbilityTarget(target, owner)) {
                continue;
            }

            this.hitTargets.add(target.getUuid());
            boolean[] damaged = {false};
            RunicSlashManager.runSuppressed(() -> damaged[0] = SimplySwordsAPI.applyEntityWeaponHit(stack, target, owner, this.damage));
            if (damaged[0]) {
                world.playSound(null, target.getX(), target.getY(), target.getZ(), SoundRegistry.ELEMENTAL_SWORD_WIND_ATTACK_02.get(), SoundCategory.PLAYERS, 0.38F, 1.35F + world.random.nextFloat() * 0.15F);
                world.spawnParticles(ParticleTypes.SWEEP_ATTACK, target.getX(), target.getBodyY(0.62), target.getZ(), 1, 0.0, 0.0, 0.0, 0.0);
                world.spawnParticles(ParticleTypes.ENCHANTED_HIT, target.getX(), target.getBodyY(0.62), target.getZ(), 8, 0.25, 0.2, 0.25, 0.0);
            }
        }
    }

private Entity getOwnerEntity(ServerWorld world) {
        int ownerId = this.dataTracker.get(OWNER_ID);
        Entity owner = ownerId >= 0 ? world.getEntityById(ownerId) : null;
        if (owner != null || this.ownerUuid == null) {
            return owner;
        }
        return world.getEntity(this.ownerUuid);
    }

@Override
    protected void writeCustomDataToNbt(NbtCompound nbt) {
        if (this.ownerUuid != null) {
            nbt.putUuid("owner_uuid", this.ownerUuid);
        }
        nbt.putDouble("max_distance", this.maxDistance);
        nbt.putDouble("traveled", this.traveled);
        nbt.putFloat("damage", this.damage);
        ItemStack stack = this.dataTracker.get(WEAPON_STACK);
        if (!stack.isEmpty()) {
            nbt.put("weapon_stack", stack.encode(this.getRegistryManager()));
        }
        nbt.putInt("owner_id", this.dataTracker.get(OWNER_ID));
        nbt.putFloat("width", this.dataTracker.get(WIDTH));
    }

@Override
    protected void readCustomDataFromNbt(NbtCompound nbt) {
        this.ownerUuid = nbt.containsUuid("owner_uuid") ? nbt.getUuid("owner_uuid") : null;
        this.maxDistance = nbt.getDouble("max_distance");
        this.traveled = nbt.getDouble("traveled");
        this.damage = nbt.getFloat("damage");
        if (nbt.contains("weapon_stack")) {
            this.dataTracker.set(WEAPON_STACK, ItemStack.fromNbt(this.getRegistryManager(), nbt.getCompound("weapon_stack")).orElse(ItemStack.EMPTY));
        }
        if (nbt.contains("owner_id")) {
            this.dataTracker.set(OWNER_ID, nbt.getInt("owner_id"));
        }
        if (nbt.contains("width")) {
            this.dataTracker.set(WIDTH, nbt.getFloat("width"));
        }
    }

@Override
    public void onSwing(ItemStack stack, ServerWorld world, LivingEntity user, Hand hand) {
        RunicSlashManager.tryFire(world, user, stack);
    }

@Inject(method = "swingHand(Lnet/minecraft/util/Hand;Z)V", at = @At("TAIL"))
    public void simplyswords$triggerRunicPowerOnSwing(Hand hand, boolean fromServerPlayer, CallbackInfo ci) {
        LivingEntity livingEntity = (LivingEntity) (Object) this;
        if (!(livingEntity.getWorld() instanceof ServerWorld world) || RunicSlashManager.isSuppressed()) {
            return;
        }

        ItemStack stack = livingEntity.getStackInHand(hand);
        if (!stack.isEmpty()) {
            SimplySwordsAPI.onWeaponSwing(stack, world, livingEntity, hand);
        }
    }

public static boolean applyEntityWeaponHit(ItemStack stack, LivingEntity target, LivingEntity actor, float damage) {
        if (stack == null || stack.isEmpty() || target == null || actor == null
                || !(actor.getWorld() instanceof ServerWorld world) || target.getWorld() != world
                || !target.isAlive()) {
            return false;
        }
        if (IgnoredEntities.isIgnored(target)) {
            return false;
        }

        Vec3d facing = actor.getRotationVec(1.0F);
        if (facing.lengthSquared() < 0.0001) {
            facing = target.getPos().subtract(actor.getPos());
        }
        if (facing.lengthSquared() < 0.0001) {
            facing = Vec3d.fromPolar(0.0F, actor.getYaw());
        }
        facing = facing.normalize();

        DelegatedWeaponHitContext context = new DelegatedWeaponHitContext(actor instanceof ServerPlayerEntity player ? player : null, actor, actor.getPos(), facing);
        DelegatedWeaponHitContext previousContext = DELEGATED_WEAPON_HIT_CONTEXT.get();
        DELEGATED_WEAPON_HIT_CONTEXT.set(context);
        try (var ignored = CombatProvenanceApi.scope(
                CombatProvenanceApi.from(stack, actor))) {
            DamageSource source = getWeaponDamageSource(actor);
            float modifiedDamage = WeaponImplicitRegistry.modifyDamage(stack, target, source, damage);
            target.timeUntilRegen = 0;
            boolean[] damaged = {false};
            WeaponImplicitRegistry.runSuppressed(() -> damaged[0] = target.damage(source, modifiedDamage));
            target.timeUntilRegen = 0;
            if (!damaged[0]) {
                return false;
            }

            EnchantmentHelper.onTargetDamaged(world, target, source, stack);
            WeaponImplicitRegistry.onHit(stack, target, actor, modifiedDamage);
            Item item = stack.getItem();
            if (item instanceof SwordItem) {
                NecromanticArsenalPower.runSuppressed(() -> item.postHit(stack, target, actor));
            }
            return true;
        } finally {
            if (previousContext == null) DELEGATED_WEAPON_HIT_CONTEXT.remove();
            else DELEGATED_WEAPON_HIT_CONTEXT.set(previousContext);
        }
    }
